import org.junit.Test;
import static org.junit.Assert.*;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.TextNode;

public class TextNodeTest {

    @Test
    public void nodeName_EmptyText_ReturnsEmptyString() {
        TextNode node = new TextNode("");
        assertEquals("", node.nodeName());
    }

    @Test
    public void text_EmptyText_ReturnsEmptyString() {
        TextNode node = new TextNode("");
        assertEquals("", node.text());
    }

    @Test
    public void text_SimpleText_ReturnsSimpleText() {
        TextNode node = new TextNode("Hello World");
        assertEquals("Hello World", node.text());
    }

    @Test
    public void text_MultipleSpaces_ReturnsTrimmedText() {
        TextNode node = new TextNode("   Hello   World  ");
        assertEquals("Hello World", node.text());
    }

    @Test
    public void isBlank_EmptyText_ReturnsTrue() {
        TextNode node = new TextNode("");
        assertTrue(node.isBlank());
    }

    @Test
    public void isBlank_NonEmptyText_ReturnsFalse() {
        TextNode node = new TextNode("Hello World");
        assertFalse(node.isBlank());
    }

    @Test
    public void splitText_SplitAtOneChar_ReturnsNewTextNode() {
        TextNode node = new TextNode("Hello\nWorld");
        TextNode result = node.splitText(0);
        assertNotNull(result);
        assertEquals(2, result.nodes().size());
        assertEquals("Hello", result.text());
        assertEquals("World", result.nodes().get(1).text());
    }

    @Test
    public void clone_ReturnsNewTextNode() {
        TextNode original = new TextNode("Hello World");
        TextNode clone = original.clone();
        assertNotNull(clone);
        assertNotSame(original, clone);
        assertEquals("Hello World", clone.text());
    }

    @Test
    public void createFromEncoded_ParsesStringCorrectly() throws IOException {
        Document document = Document.parseText("a > b < c");
        TextNode node = TextNode.createFromEncoded(document.html().trim());
        assertNotNull(node);
        assertEquals(3, node.nodes().size());
        assertEquals("a", node.nodes().get(0).text());
        assertEquals(">", node.nodes().get(1).nodeName());
        assertEquals("<", node.nodes().get(2).nodeName());
    }

    @Test
    public void normaliseWhitespace_SimpleText_ReturnsTrimmedString() {
        assertEquals("Hello World", TextNode.normaliseWhitespace("   Hello   World  "));
    }

    @Test
    public void stripLeadingWhitespace_SimpleText_ReturnsTrimmedString() {
        assertEquals("Hello World", TextNode.stripLeadingWhitespace("   Hello   World  "));
    }

    @Test
    public void lastCharIsWhitespace_NonWhitespaceChar_ReturnsFalse() {
        assertFalse(TextNode.lastCharIsWhitespace(new StringBuilder("Hello")));
        assertTrue(TextNode.lastCharIsWhitespace(new StringBuilder(" ")));
    }
}
